INSERT INTO `protocols` (id, name, parameters, bulk_modifier, description, observable, reportable, multiplier) VALUES
  (1, 'Dump resource', 1, 100, '[R 1 perform]: Dump one unit of resource R into space.', 1, 1, 0),
  (7, 'Sell resource', 3, 100, '[P M R 7 perform]: Places order to sell resource R at price P, keeping min M units at drone''s cargo hold.', 1, 1, 0),
  (8, 'Buy resource', 3, 100, '[P M R 8 perform]: Places order to buy resource R at price P, keeping max M units at drone''s cargo hold.', 1, 1, 0),
  (10, 'Push resource', 2, 100, '[R D 10 perform]: Delivers one unit of resource R to drone D.  It takes one minute of game time.', -1, -1, 1),
  (11, 'Pull resource', 2, 100, '[R D 11 perform]: Pulls one unit of resource R from drone D. It takes one minute of game time.', -1, -1, 1),
  (5001, 'Activate Engine I', 0, 100, '[N 5001 perform]: Moves the spacecraft to the the astronimical object whoes Location ID is N.', 1, 1, 0),
  (5911, 'Import Resource', 1, 100, '[N 5911 perform]: Imports resource N from the planet surface.  Requires an import station.', 1, 1, 0),
  (5921, 'Export Resource', 1, 100, '[N 5921 perform]: Exports resource N from the cargo bay to the planet surface.  Requires an export station.', 1, 1, 0),
  (11000, 'Mine magmite', 0, 100, '[11000 perform]: Mine magmite from the planet''s surface, if present. Uses a Slug (A1) mining module. Takes 1 hour.', -1, -1, 0),
